const v = $('VALIDATE').first().json;
const base = { lead_id: t.lead_id, conversation_id: t.conversation_id, organization_id: t.organization_id, channel: t.channel };
return [{ json: { ...base, mode: 'DISQUALIFIED', router_reason: v.in_service_area === false ? 'property is outside our service area' : 'service not offered' } }];

